def feature(text: str) -> float:
    "Entropy of the word distribution in the text"
    from collections import Counter
    import math
    words = text.split()
    if not words:
        return 0.0
    word_counts = Counter(words)
    total_words = len(words)
    entropy = -sum((count / total_words) * math.log(count / total_words, 2) for count in word_counts.values())
    return float(entropy)

